-- Check what equipstatus, calibrstatus, coolsysstatus values look like for non-nominal ones
SELECT DISTINCT equipstatus FROM telescopes WHERE equipstatus != 'Operational';
SELECT DISTINCT calibrstatus FROM telescopes WHERE calibrstatus != 'Current';
SELECT DISTINCT coolsysstatus FROM telescopes WHERE coolsysstatus != 'Normal';
